let prefs={lang:'ro',theme:matchMedia('(prefers-color-scheme: light)').matches?'light':'dark',environment:'aqua',lighting:'day',weather:'clear',quality:'auto',easy:true,speed:.8,motion:matchMedia('(prefers-reduced-motion: reduce)').matches,contrast:false,sound:true,effectVolume:65,ambienceVolume:25,audioVersion:1,assist:true,relaxed:false,timer:false,controls:'arrows',...saved.prefs};if(!['ro','en'].includes(prefs.lang))prefs.lang='ro';
let progress={level:1,best:0,wallet:0,skins:['classic'],skin:'classic',...saved.progress};progress.level=Math.max(1,Math.min(100,Number(progress.level)||1));progress.best=Math.max(0,Number(progress.best)||0);progress.wallet=Math.max(0,Number(progress.wallet)||0);if(!Array.isArray(progress.skins))progress.skins=['classic'];
if(typeof URLSearchParams!=='undefined'){const lang=new URLSearchParams(window.location?.search||'').get('lang');if(['ro','en'].includes(lang))prefs.lang=lang}
