let mode='story',level=progress.level,state='ready',snake=[],dir={x:1,y:0},pendingDir=dir,food=[],chains=[],score=0,removed=0,total=0,target={lane:0,index:0},aiming=false,elapsed=0,freeze=0,stepClock=0,random=Math.random,wallPhase=0,prismNext=false,bombNext=false,magnet=0,last=0,liveTimer=0,visualSnake=[],effects=[],renderDt=.016,headAngle=0,visualClock=0,frameEma=.016,gfxLow=false,canvasRatio=1,focusMode=false,tutorialStep=0,guidePhase=0,matchCount=0,maxCombo=0,gatePasses=0;
